-- ===========================================================================
--  Mini-magazin (shop) — database-level GRANT/REVOKE
--  Migration: Shop (client, 2026-10-15; docs/modules/shop.md)
-- ===========================================================================
--
--  DO NOT EDIT THIS FILE. A migration is applied once and then frozen; a change
--  here would make new databases silently differ from old ones. A change needs a
--  new migration and a new .sql file (same rule as cash_boxes_guards.sql).
--
--  WHY IN THE MIGRATION: `deploy/init-roles.sql` grants `app_rw` full CRUD on
--  every new table through ALTER DEFAULT PRIVILEGES, so the moment
--  `CREATE TABLE shop_sale_lines` finishes, `app_rw` can DELETE from it. Taking
--  that back must not be a manual step somebody forgets.
--
--  TWO TABLES, TWO RULES
--  ---------------------
--    * `shop_products`   — a catalogue (name, kind, price). Prices change, items
--                          are renamed and switched off: UPDATE stays. DELETE also
--                          stays, for a product that was never sold (a typo): a
--                          sold product is held by the RESTRICT foreign key from
--                          `shop_sale_lines`, and the service refuses first with a
--                          readable 409 — the `transaction_types` pattern.
--    * `shop_sale_lines` — what a cash-box Kirim sold. A money record exactly like
--                          the `cash_box_transactions` row it belongs to: INSERT
--                          and SELECT only. A wrong sale is cancelled by storno of
--                          that Kirim; its lines stay as they were.
--
--  No `app_rw` role (the test harness) — skip quietly, as the other guard files do.
-- ===========================================================================

DO $guards$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_rw') THEN
        RAISE NOTICE '[shop_guards] `app_rw` roli topilmadi — GRANT/REVOKE o''tkazib '
                     'yuborildi. Bu bazada savdo qatorlari uchun moliyaviy o''zgarmaslik '
                     'YO''Q. deploy/init-roles.sql ni ishga tushiring.';
        RETURN;
    END IF;

    -- ---- shop_sale_lines: money record, INSERT-only ----
    EXECUTE 'REVOKE UPDATE, DELETE, TRUNCATE ON public.shop_sale_lines FROM app_rw';
END
$guards$;
